css:
.print-format {
 font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
 max-width: 800px;
 margin: 0 auto;
 padding: 40px;
}
.company-header {
 text-align: center;
 margin-bottom: 30px;
}
.company-header h1 {
 color: #1e293b;
 font-size: 28px;
 margin: 0;
}
.offer-title {
 text-align: center;
 font-size: 22px;
 color: #2563eb;
 margin: 20px 0;
 font-weight: 600;
}
.content {
 line-height: 1.8;
 color: #334155;
}
.details-table {
 width: 100%;
 margin: 20px 0;
 border-collapse: collapse;
}
.details-table td {
 padding: 10px;
 border-bottom: 1px solid #e2e8f0;
}
.details-table td:first-child {
 font-weight: 600;
 color: #475569;
 width: 40%;
}
.signature-section {
 margin-top: 50px;
}
.signature-line {
 border-top: 1px solid #cbd5e1;
 width: 250px;
 margin-top: 50px;
 padding-top: 8px;
}
.footer {
 margin-top: 40px;
 text-align: center;
 font-size: 12px;
 color: #94a3b8;
 border-top: 1px solid #e2e8f0;
 padding-top: 15px;
}
